import json
import logging
import boto3
import cfnresponse
import time

logger = logging.getLogger()
logger.setLevel(logging.INFO)

ec2 = boto3.client('ec2')
elb = boto3.client('elbv2')

def create_nodes(properties, physical_id):
    node_type = properties['NodeType']
    count = int(properties['Count'])
    instance_type = properties['InstanceType']
    image_id = properties['ImageId']
    key_name = properties['KeyName']
    subnet_id = properties['SubnetId']
    security_group = properties['SecurityGroup']
    target_group = properties.get('TargetGroup')
    region = properties['Region']

    node_ids = []
    node_ips = []

    for i in range(count):
        # Generate node index (1-based)
        node_idx = i + 1

        # Create UserData with proper TEE configuration
        user_data = generate_user_data(node_type, node_idx, region)

        # Launch instance
        response = ec2.run_instances(
            ImageId=image_id,
            InstanceType=instance_type,
            KeyName=key_name,
            MaxCount=1,
            MinCount=1,
            NetworkInterfaces=[{
                'DeviceIndex': 0,
                'SubnetId': subnet_id,
                'Groups': [security_group],
                'AssociatePublicIpAddress': True
            }],
            UserData=user_data,
            TagSpecifications=[{
                'ResourceType': 'instance',
                'Tags': [
                    {'Key': 'Name', 'Value': f'{node_type.lower()}-node-{node_idx}'},
                    {'Key': 'TEEType', 'Value': node_type},
                    {'Key': 'NodeIndex', 'Value': str(node_idx)}
                ]
            }]
        )

        instance_id = response['Instances'][0]['InstanceId']
        node_ids.append(instance_id)

        # Wait for instance to be running and initialized
        waiter = ec2.get_waiter('instance_running')
        waiter.wait(InstanceIds=[instance_id])

        # Get instance information
        instance_info = ec2.describe_instances(InstanceIds=[instance_id])
        public_ip = instance_info['Reservations'][0]['Instances'][0]['PublicIpAddress']
        node_ips.append(public_ip)

        # Register instance with target group if provided
        if target_group:
            elb.register_targets(
                TargetGroupArn=target_group,
                Targets=[{
                    'Id': instance_id,
                    'Port': 80
                }]
            )

        # Add a slight delay between instance creations to allow for auto-mesh discovery
        if i < count - 1:
            time.sleep(5)

    return {'NodeIds': node_ids, 'NodeIPs': node_ips}

