    # Convert to base64
    import base64
    return base64.b64encode(user_data.encode()).decode()

def delete_nodes(properties, physical_id):
    # Parse the physical_id to get the instance IDs
    if physical_id.startswith('nodes:'):
        node_info = json.loads(physical_id[6:])
        node_ids = node_info.get('NodeIds', [])

        # Delete instances
        if node_ids:
            ec2.terminate_instances(InstanceIds=node_ids)

            # Wait for instances to be terminated
            waiter = ec2.get_waiter('instance_terminated')
            waiter.wait(InstanceIds=node_ids)

def update_nodes(properties, physical_id):
    # For updates, delete old instances and create new ones
    delete_nodes(properties, physical_id)
    return create_nodes(properties, physical_id)

def handler(event, context):
    logger.info('Event: %s', event)
    properties = event['ResourceProperties']

    # Validate required properties
    for prop in ['NodeType', 'Count', 'InstanceType', 'ImageId', 'KeyName', 'SubnetId', 'SecurityGroup', 'Region']:
        if prop not in properties:
            return cfnresponse.send(event, context, cfnresponse.FAILED, {
                'Error': f'Missing required property: {prop}'
            })

    physical_id = event.get('PhysicalResourceId')
    response_data = {}

    try:
        if event['RequestType'] == 'Create':
            result = create_nodes(properties, physical_id)
            response_data = result
            physical_id = 'nodes:' + json.dumps(result)
        elif event['RequestType'] == 'Update':
            result = update_nodes(properties, physical_id)
            response_data = result
            physical_id = 'nodes:' + json.dumps(result)
        elif event['RequestType'] == 'Delete':
            delete_nodes(properties, physical_id)

        cfnresponse.send(event, context, cfnresponse.SUCCESS, response_data, physical_id)
    except Exception as e:
        logger.exception('Failed to process request')
        cfnresponse.send(event, context, cfnresponse.FAILED, {
            'Error': str(e)
        }, physical_id)
